"""Configuration loading helpers."""

from pathlib import Path


def config_path(name: str) -> Path:
    return Path("configs") / name


def load_retry_policy() -> dict:
    return {"initial_delay_seconds": 30, "max_attempts": 5}


def _parse_simple_yaml(text: str) -> dict:
    """Parse a minimal subset of YAML: nested mappings of scalar values.

    This intentionally avoids a third-party YAML dependency. It supports the
    flat, two-level structure used by ``configs/feature_flags.yaml``.
    """
    result: dict = {}
    current_section: str | None = None
    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if not line.strip() or line.strip().startswith("#"):
            continue
        stripped = line.lstrip()
        indent = len(line) - len(stripped)
        if ":" not in stripped:
            continue
        key, _, value = stripped.partition(":")
        key = key.strip()
        value = value.strip()
        if indent == 0:
            current_section = key
            result.setdefault(key, {})
        else:
            section = current_section if current_section is not None else ""
            result.setdefault(section, {})[key] = _parse_scalar(value)
    return result


def _parse_scalar(value: str):
    if value == "":
        return None
    lowered = value.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    if lowered in ("null", "~"):
        return None
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    return value


def load_feature_flags() -> dict:
    """Load feature flags from ``configs/feature_flags.yaml``.

    Returns an empty mapping when the file is missing or unreadable so that
    callers can fall back to their default behavior.
    """
    path = config_path("feature_flags.yaml")
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {}
    return _parse_simple_yaml(text)

"""Event-driven notification dispatch."""

from src.common.events import EventEnvelope, INVOICE_RETRY_REQUESTED, ORDER_CANCELLED
from src.common.settings import load_feature_flags
from src.notifications.email import EmailSender
from src.notifications.templates import TEMPLATE_INVOICE_RETRY, TEMPLATE_ORDER_CANCELLED


class NotificationDispatcher:
    """Routes events to email templates."""

    def __init__(self, sender: EmailSender | None = None) -> None:
        self.sender = sender or EmailSender()

    def _email_dispatch_enabled(self) -> bool:
        flags = load_feature_flags()
        notifications = flags.get("notifications")
        if not isinstance(notifications, dict):
            return True
        value = notifications.get("email_dispatch_enabled")
        # Dispatch is suppressed only when the flag is explicitly false.
        return value is not False

    def handle(self, event: EventEnvelope) -> None:
        if not self._email_dispatch_enabled():
            return
        if event.name == ORDER_CANCELLED:
            self.sender.send("ops@example.com", TEMPLATE_ORDER_CANCELLED, event.payload)
        if event.name == INVOICE_RETRY_REQUESTED:
            self.sender.send("billing@example.com", TEMPLATE_INVOICE_RETRY, event.payload)
